from pathlib import Path
import importlib.util,json
r=Path(__file__).resolve().parent;stage=json.loads((r/'stage.json').read_text());baseline=json.loads((r/'baseline.json').read_text())
p=importlib.util.spec_from_file_location('b',r/'vm-bridge.py');b=importlib.util.module_from_spec(p);p.loader.exec_module(b)
source='ROOT='+repr(stage['root'])+'\nMANIFEST='+repr(baseline['program'])+'\nNODE='+repr("import fs from 'node:fs';import assert from 'node:assert/strict';import {requestSecurityService} from './package/lib/redteam/personal-security-service.mjs';\nconst root=process.cwd(),stage=JSON.parse(fs.readFileSync(root+'/stage.json'));\nconst call=input=>requestSecurityService({engagement:stage.engagement,...input},{socketPath:root+'/run/harness-security.sock',model:false});\nconst status=await call({op:'securityJoint',action:'status',requestId:'native-import-20261110-01'});assert.equal(status.ok,true);const id=status.task.id,snapshot=status.task.snapshot.id;\nconst report={version:1,engagement:stage.engagement,task:null,findings:[],files:[],exclusions:[],diagnostics:[],artifacts:[]},pages=[];\nfor(const section of ['findings','files','exclusions','diagnostics','artifacts']){let cursor,total;const seen=new Set();for(let i=0;i<100;i++){\nconst v=await call({op:'securityJoint',action:'report',id,section,limit:5,...(cursor?{cursor}:{})});assert.equal(v.ok,true);assert.equal(v.task.id,id);assert.equal(v.task.snapshot.id,snapshot);assert.equal(v.page.section,section);if(total!==undefined)assert.equal(v.page.total,total);total=v.page.total;report.task=v.task;report[section].push(...v.page.items);pages.push({section,count:v.page.items.length,total,complete:v.page.complete});if(v.page.complete){assert.equal(report[section].length,total);break}assert.ok(v.page.nextCursor&&!seen.has(v.page.nextCursor));seen.add(v.page.nextCursor);cursor=v.page.nextCursor;if(i===99)throw Error('page cap');}}\nconsole.log(JSON.stringify({report,pages}));\n")+'\n'+(r/'collect-script.txt').read_text()
v=b.call(source,45)
(r/'collected.json').write_text(json.dumps(v,ensure_ascii=False,indent=2)+'\n');print(json.dumps(v['summary']))
